.related-card:hover {
  border-color: var(--teal);
  box-shadow: var(--shadow-md);
}
.related-card-title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 0.75rem;
}
.related-card-desc {
  font-size: 0.875rem;
  color: var(--gray-500);
  line-height: 1.6;
}

/* Property Types CTA */
.prop-types-cta {
  padding: 5rem 0;
  background: linear-gradient(135deg, var(--navy) 0%, #162440 100%);
}
.prop-types-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1rem;
  margin-top: 2.5rem;
}
.prop-type-btn {
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: var(--radius-md);
  padding: 1.5rem 1rem;
  color: rgba(255,255,255,0.75);
  font-size: 0.875rem;
  font-weight: 500;
  text-align: center;
  transition: all var(--transition);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
}
.prop-type-btn:hover {
  background: rgba(0,166,147,0.12);
  border-color: var(--teal);
  color: var(--white);
}
.prop-type-icon { color: var(--teal); }

