.partnership { padding: 5rem 0; background: var(--white); }
.partnership-inner {
  background: linear-gradient(135deg, var(--navy) 0%, var(--green) 100%);
  border-radius: var(--radius-xl);
  padding: 4rem;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4rem;
  align-items: center;
  position: relative;
  overflow: hidden;
}
.partnership-inner::before {
  content: '';
  position: absolute;
  top: -60%;
  right: -5%;
  width: 400px;
  height: 400px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(0,166,147,0.15) 0%, transparent 70%);
  pointer-events: none;
}
.partnership-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 1rem;
  letter-spacing: -0.02em;
}
.partnership-body {
  font-size: 1rem;
  color: rgba(255,255,255,0.72);
  line-height: 1.7;
}
.partnership-stats {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  flex-shrink: 0;
}
.pstat-num {
  font-size: 2.25rem;
  font-weight: 800;
  color: var(--teal);
  letter-spacing: -0.03em;
  line-height: 1;
}
.pstat-label {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.55);
  margin-top: 0.125rem;
}

/* Related Insights (service pages) */
.related-insights { padding: 5rem 0; background: var(--gray-50); }

/* ===========================
   FOOTER
=========================== */
.site-footer {
  background: var(--navy);
  padding: 5rem 0 2rem;
}
.footer-top {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 3rem;
  padding-bottom: 3rem;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.footer-brand .logo { margin-bottom: 1.25rem; font-size: 1.125rem; }
.footer-brand p {
  font-size: 0.9rem;
  color: rgba(255,255,255,0.5);
  line-height: 1.7;
  max-width: 280px;
}
.footer-col h5 {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.4);
  margin-bottom: 1.25rem;
}
.footer-col ul { display: flex; flex-direction: column; gap: 0.625rem; }
.footer-col ul a {
  color: rgba(255,255,255,0.65);
  font-size: 0.9rem;
  transition: color var(--transition);
}
.footer-col ul a:hover { color: var(--white); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 2rem;
  gap: 2rem;
  flex-wrap: wrap;
}
.footer-legal {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.35);
}
.footer-legal-links {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
}
.footer-legal-links a {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.35);
  transition: color var(--transition);
}
.footer-legal-links a:hover { color: rgba(255,255,255,0.7); }

/* ===========================
   FEATURED PARTNERS CAROUSEL
=========================== */
.featured-partners { padding: 5rem 0; background: var(--gray-50); }
.carousel-container { position: relative; overflow: hidden; margin-top: 2.5rem; }
.carousel-track {
  display: flex;
  gap: 1.5rem;
  transition: transform 0.35s ease;
}
.carousel-slide {
  min-width: calc(33.333% - 1rem);
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  border: 1px solid var(--gray-200);
  flex-shrink: 0;
}
.carousel-slide-tag {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--teal);
  margin-bottom: 0.75rem;
}
.carousel-slide-title {
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 0.75rem;
  line-height: 1.35;
}
.carousel-slide-body {
  font-size: 0.875rem;
  color: var(--gray-500);
  line-height: 1.65;
}
.carousel-controls {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-top: 2rem;
}
.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--navy);
  transition: all var(--transition);
  cursor: pointer;
  background: var(--white);
}
.carousel-btn:hover {
  background: var(--navy);
  color: var(--white);
  border-color: var(--navy);
}
.carousel-dots { display: flex; gap: 0.5rem; margin-left: 0.5rem; }
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-300);
  cursor: pointer;
  transition: background var(--transition);
}
.carousel-dot.active { background: var(--teal); }

/* ===========================
   RESPONSIVE
=========================== */
@media (max-width: 1024px) {
  .main-nav, .header-actions .header-cta { display: none; }
  .hamburger { display: flex; }
  .header-search-btn { display: none; }

  .grid-4, .commitment-grid, .topics-list, .prop-types-grid { grid-template-columns: repeat(2, 1fr); }
  .grid-3, .service-cards-grid, .capabilities-grid, .insights-grid, .related-list { grid-template-columns: repeat(2, 1fr); }
  .footer-top { grid-template-columns: 1fr 1fr; }
  .about-inner { gap: 3rem; }
  .deal-flow-inner { grid-template-columns: 1fr; }
  .deal-flow-stats { justify-content: flex-start; }
}

@media (max-width: 768px) {
  .container, .container-wide { padding: 0 1.25rem; }
  .section, .section-lg { padding: 4rem 0; }
  .section-sm { padding: 3rem 0; }

  .grid-2, .grid-3, .grid-4, .grid-6,
  .service-cards-grid, .capabilities-grid, .insights-grid,
  .commitment-grid, .topics-list, .prop-types-grid, .related-list { grid-template-columns: 1fr; }

  .about-inner { grid-template-columns: 1fr; }
  .about-stat-card { position: static; margin-top: 1rem; }
  .wwd-inner { grid-template-columns: 1fr; }
  .wwd-tabs { flex-direction: row; overflow-x: auto; padding: 0; }
  .wwd-tab { padding: 1rem 1.25rem; border-left: none; border-bottom: 3px solid transparent; white-space: nowrap; }
  .wwd-tab.active { border-bottom-color: var(--teal); border-left-color: transparent; }
  .wwd-panels { padding: 2rem 1.5rem; }
  .newsletter-inner { flex-direction: column; }
  .footer-top { grid-template-columns: 1fr; gap: 2rem; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
  .hero-title { font-size: 2rem; }
  .section-header { flex-direction: column; align-items: flex-start; }
  .insight-list-card { grid-template-columns: 80px 1fr; gap: 1rem; }
  .insight-thumb { width: 80px; height: 70px; }
  .partnership-inner { grid-template-columns: 1fr; padding: 2.5rem; }
  .partnership-stats { flex-direction: row; gap: 2rem; }
  .deal-flow-stats { flex-direction: column; gap: 1.5rem; }
  .carousel-slide { min-width: calc(100% - 0px); }
}

@media (max-width: 480px) {
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; justify-content: center; }
  .newsletter-form { flex-direction: column; }
  .newsletter-input { min-width: 100%; }
}

/* Smooth scroll offset for fixed header */
[id] { scroll-margin-top: 80px; }

/* Divider */
.divider { height: 1px; background: var(--gray-200); }

/* SVG Icon sizes */
.icon-sm { width: 16px; height: 16px; }
.icon-md { width: 20px; height: 20px; }
.icon-lg { width: 24px; height: 24px; }
.icon-xl { width: 28px; height: 28px; }

